<template><section class="leader"><div class="head"><div><small>ONLINE TOP 10</small><h3>游戏排行榜</h3></div><button :disabled="busy" @click="submit">{{ busy?'提交中…':`提交成绩 ${score}` }}</button></div><div class="rows"><div v-for="(x,i) in rows" :key="x.ip" class="row"><b>{{ i+1 }}</b><code>{{ x.ip }}</code><span>{{ x.location||'未知地区' }}</span><strong>{{ x.score }}</strong></div><p v-if="!rows.length">还没有成绩，来当第一名吧！</p></div><div v-if="tip" class="tip">{{ tip }}</div></section></template>
<script setup lang="ts">import{onMounted,ref}from'vue';const p=defineProps<{game:string,score:number}>();type Row={ip:string,location:string,score:number};const rows=ref<Row[]>([]),busy=ref(false),tip=ref('');async function req(url:string,o?:RequestInit){const r=await fetch(url,{cache:'no-store',headers:{'Content-Type':'application/json'},...o});const text=await r.text();let x:any=null;try{x=JSON.parse(text)}catch{throw Error(`HTTP ${r.status}${text?`：${text}`:''}`)}if(!r.ok||!x.success)throw Error(x?.message||`HTTP ${r.status}`);return x.data}async function load(){try{rows.value=await req(`/api/game-scores/${p.game}`)}catch{tip.value='排行榜暂时无法加载'}}async function submit(){busy.value=true;tip.value='';try{rows.value=await req('/api/game-scores',{method:'POST',body:JSON.stringify({game:p.game,score:p.score})});tip.value='成绩已提交，同一 IP 仅保留最高分'}catch(e){tip.value=`提交失败：${e instanceof Error?e.message:'请稍后再试'}`}finally{busy.value=false}}onMounted(load)</script>
<style scoped>.leader{max-width:520px;margin:30px auto 0;padding:18px;background:var(--c-bg-card);border:1px solid var(--c-border);border-radius:14px}.head{display:flex;justify-content:space-between;align-items:center}.head small{color:var(--c-purple);letter-spacing:2px}.head h3{margin:4px 0;color:var(--c-text)}button{border:0;border-radius:8px;padding:9px 12px;background:linear-gradient(135deg,var(--c-purple),var(--c-cyan));color:white;font-weight:700}.rows{display:grid;gap:5px;margin-top:12px}.row{display:grid;grid-template-columns:25px 105px 1fr 60px;gap:7px;padding:7px 8px;background:var(--c-bg-card2);border-radius:7px;font-size:11px}.row b{color:var(--c-purple)}.row code{color:var(--c-text-2)}.row span{color:var(--c-text-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.row strong{text-align:right;color:var(--c-cyan)}.rows p,.tip{text-align:center;color:var(--c-text-3);font-size:12px}.tip{color:var(--c-green);margin-top:8px}</style>
